                            <div class="task-actions">
                                @if (GetColumnIndex(column) > 0)
                                {
                                    var leftStatus = columns[GetColumnIndex(column) - 1];
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => MoveTask(task.Id, leftStatus)">Move Left</button>
                                }
                                @if (GetColumnIndex(column) < columns.Length - 1)
                                {
                                    var rightStatus = columns[GetColumnIndex(column) + 1];
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="() => MoveTask(task.Id, rightStatus)">Move Right</button>
                                }
                            </div>
                        </div>
                    }
                </div>

                @if (addingToColumn == column)
                {
                    <div class="add-task-form">
                        <input type="text" @bind="newTitle" placeholder="Title" class="form-control" />
                        <input type="text" @bind="newAssignee" placeholder="Assignee" class="form-control" />
                        <select @bind="newPriority" class="form-control">
                            <option value="High">High</option>
                            <option value="Medium">Medium</option>
                            <option value="Low">Low</option>
                        </select>
                        <input type="date" @bind="newDueDate" class="form-control" />
                        <div class="form-buttons">
                            <button class="btn btn-primary btn-sm" @onclick="() => SaveTask(column)">Save</button>
                            <button class="btn btn-secondary btn-sm" @onclick="CancelAdd">Cancel</button>
                        </div>
                    </div>
                }
                else
                {
                    <button class="btn btn-outline-primary btn-sm add-task-btn" @onclick="() => ShowAddForm(column)">Add Task</button>
                }
            </div>
        }
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchQuery = string.Empty;

    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today;

    private readonly string[] columns = { "To Do", "In Progress", "Done" };

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status) =>
        allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status) =>
        allTasks
            .Where(t => t.Status == status)
            .Where(t => string.IsNullOrEmpty(searchQuery) || t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase))
            .ToList();

    private int GetColumnIndex(string column) => Array.IndexOf(columns, column);

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            allTasks[allTasks.IndexOf(task)] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today;
    }

    private void CancelAdd() => addingToColumn = null;

    private async Task SaveTask(string column)
    {
        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            allTasks.Add(created with { Status = column });
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

